SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_1578
WHERE (it1.id IN ('18')) AND non_leaf_1578.n_id = pi.person_id AND (it2.id IN ('29')) AND (rt.role IN ('actress','cinematographer','composer','costume designer','director','editor','guest','miscellaneous crew','producer','production designer','writer')) AND it2.id = pi.info_type_id AND (mi1.info ILIKE '%paul%') AND (kt.kind IN ('episode','tv mini series','video game','video movie')) AND (pi.info ILIKE '%da%');